// The frontend bundles the *compiled* contract from ../src/managed, which is
// generated by compactc and gitignored, so a fresh clone does not have it.
// Compile it on demand; no-op once it exists.
import { existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const frontend = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repo = resolve(frontend, '..');
const compiled = resolve(repo, 'src/managed/medpass/contract/index.js');

if (existsSync(compiled)) process.exit(0);

const has = spawnSync('compactc', ['--version'], { stdio: 'ignore' }).status === 0;
if (!has) {
  console.error(
    `\nMissing compiled contract: ${compiled}\n` +
      'and `compactc` is not on PATH, so it cannot be generated.\n\n' +
      'Install the Compact compiler (v0.31.1), then re-run:\n' +
      '  npm run build   # in the repo root: compiles src/medpass.compact\n\n' +
      'See the README "Requirements" section for the compactc download link.\n',
  );
  process.exit(1);
}

console.log('[ensure-contract] compiling src/medpass.compact -> src/managed/medpass ...');
const r = spawnSync('compactc', ['src/medpass.compact', 'src/managed/medpass'], {
  cwd: repo,
  stdio: 'inherit',
});
process.exit(r.status ?? 1);
